# Balduzzi - Homemaker Home Health Aide.
# Unit list: 7th edition (2016), from the publisher's table of contents on cengage.com. The book is organized in units.
# Summaries cover each unit's standard topics; they are written for this site, not copied from the book.

C = [
    (1, "Home Health Services", [
        "Home health care lets clients receive care in their own homes instead of hospitals or nursing homes. Demand has grown because of an aging population, shorter hospital stays, and cost savings. The care team includes the client and family, physician, registered nurse case manager, therapists, social workers, and home health aides.",
        "Home care is paid for by Medicare (for homebound clients with skilled needs), Medicaid, private insurance, long-term care insurance, and private pay. Other settings include adult day care and assisted living facilities.",
    ], ["Home care costs less than hospital care", "RN case manager supervises the plan of care", "Medicare covers homebound clients with skilled needs", "The client is the center of the care team"]),
    (2, "Home Health Aide Responsibilities and Legal Rights", [
        "Home health aides help with personal care, homemaking, and observing and reporting changes, following the care plan written by the nurse. Aides must stay within their scope of practice and never perform tasks they are not trained or allowed to do, such as giving medications unless permitted.",
        "Legal and ethical duties include respecting client rights, keeping information confidential (HIPAA), avoiding negligence, abuse, and neglect, and reporting suspected abuse. Aides must be honest, dependable, and respectful of the client's home and belongings.",
    ], ["Follow the care plan", "Stay within your scope of practice", "Keep information confidential", "Report suspected abuse or neglect"]),
    (3, "Developing Effective Communication Skills and Documentation", [
        "Good communication uses clear words, active listening, appropriate body language, and respect. Barriers include hearing or vision loss, language differences, confusion, and strong emotions. Aides adapt by speaking slowly, facing the client, and using simple words.",
        "Documentation must be accurate, objective, timely, and written in ink, recording what was observed and done. Subjective statements are what the client says; objective data is what the aide observes. Changes in condition must be reported to the supervisor promptly.",
    ], ["Active listening", "Objective = observed; subjective = reported by client", "Document accurately and promptly", "Report changes to the supervisor"]),
    (4, "Safety", [
        "Home safety focuses on preventing falls (the most common home injury among older adults), burns, poisoning, and fires. Aides remove clutter and throw rugs, ensure good lighting, use grab bars, and store chemicals and medications safely.",
        "Fire safety includes smoke detectors, an escape plan, and knowing how to use an extinguisher (PASS: Pull, Aim, Squeeze, Sweep). Aides use proper body mechanics, practice personal safety when traveling, and know emergency procedures and when to call 911.",
    ], ["Falls are the most common home injury", "Remove throw rugs and clutter", "PASS for fire extinguishers", "Know when to call 911"]),
    (5, "Homemaking Service", [
        "Homemaking services keep the client's home clean, safe, and comfortable. Tasks include light housekeeping, laundry, changing linens, shopping, meal planning and preparation, and managing a budget when asked.",
        "Aides respect the client's preferences and routines, use cleaning products safely, prevent the spread of germs in the kitchen and bathroom, and follow food safety rules.",
    ], ["Respect client preferences", "Clean kitchen and bathroom to prevent infection", "Follow food safety rules", "Use cleaning products safely"]),
    (6, "Infancy to Adolescence", [
        "Growth and development follow predictable stages. Infants develop trust and motor skills; toddlers gain independence and language; preschoolers learn through play; school-age children develop skills and friendships; and adolescents experience puberty and form identity.",
        "Aides caring for families with children should understand normal development, safety needs at each age (such as car seats, safe sleep on the back for infants, and childproofing), and signs of possible abuse.",
    ], ["Infants: trust and motor skills", "Adolescence: puberty and identity", "Safe sleep: infants on their backs", "Know signs of child abuse"]),
    (7, "Early and Middle Adulthood", [
        "Young adults establish careers, relationships, and families. Middle adults balance work, caring for children and aging parents, and physical changes such as decreased vision and menopause.",
        "Healthy lifestyle choices in adulthood, including diet, exercise, avoiding tobacco, and stress management, reduce the risk of chronic disease later.",
    ], ["Young adults: careers and relationships", "Middle adults: 'sandwich generation'", "Menopause in middle adulthood", "Healthy habits prevent chronic disease"]),
    (8, "Older Adulthood", [
        "Aging brings physical changes: thinner skin, weaker bones and muscles, slower reflexes, reduced vision and hearing, and changes in the heart, lungs, and digestion. Most older adults remain independent and mentally alert; confusion is not a normal part of aging.",
        "Psychosocial changes include retirement, loss of a spouse and friends, and moving to new living situations. Aides promote independence, dignity, and social contact.",
    ], ["Aging skin, bones, and senses change", "Confusion is not normal aging", "Promote independence and dignity", "Losses can cause loneliness and depression"]),
    (9, "Infection Control", [
        "Infection spreads through the chain of infection: infectious agent, reservoir, portal of exit, mode of transmission, portal of entry, and susceptible host. Hand hygiene is the most important way to break the chain.",
        "Standard precautions apply to all clients, using gloves, gowns, masks, and eye protection as needed. Aides handle soiled linens and waste safely, disinfect surfaces, and follow transmission-based precautions for clients with contagious diseases.",
    ], ["Chain of infection has six links", "Hand hygiene is most important", "Standard precautions for all clients", "Handle soiled linens carefully"]),
    (10, "From Wellness to Illness", [
        "Wellness includes physical, emotional, social, and spiritual health. Illness can be acute (sudden, short) or chronic (long-lasting). Aides observe signs and symptoms and report changes.",
        "Measuring vital signs (temperature, pulse, respirations, blood pressure) and height and weight helps monitor health. Pain, oxygen levels, and changes in behavior or appetite should be reported.",
    ], ["Acute = sudden; chronic = long-lasting", "Measure and report vital signs", "Observe and report changes", "Wellness has many dimensions"]),
    (11, "Mental Health", [
        "Mental health affects how people think, feel, and cope. Common conditions include depression, anxiety, bipolar disorder, and substance abuse. Older adults may experience depression after losses.",
        "Aides support clients by listening, encouraging activity, following the care plan, and reporting warning signs such as talk of suicide, changes in behavior, or refusal to eat. Defense mechanisms help people cope with stress.",
    ], ["Depression is common and treatable", "Report talk of suicide immediately", "Listen and encourage activity", "Defense mechanisms reduce anxiety"]),
    (12, "Digestion and Nutrition", [
        "The digestive system breaks down food and absorbs nutrients. A healthy diet includes all food groups (MyPlate), adequate fluids, and nutrients for the client's needs. Special diets include diabetic, low-sodium, soft, and liquid diets.",
        "Aides help with meal planning, feeding clients who need assistance, encouraging fluids, and measuring intake. Swallowing problems (dysphagia) require careful positioning and sometimes thickened liquids.",
    ], ["Follow special diets in the care plan", "Encourage fluids", "Sit clients upright to eat", "Dysphagia may need thickened liquids"]),
    (13, "Elimination", [
        "Aides help clients with urination and bowel movements using toilets, commodes, bedpans, and urinals, while maintaining privacy and dignity. They observe and report changes in urine or stool, such as blood, odor, or constipation.",
        "Care includes perineal care, catheter care (keep the bag below the bladder), and measuring output. Incontinence is managed with scheduled toileting, skin care, and protective products.",
    ], ["Provide privacy", "Keep the catheter bag below the bladder", "Report changes in urine or stool", "Scheduled toileting helps incontinence"]),
    (14, "Integumentary System", [
        "The skin protects the body, regulates temperature, and senses touch. Aging skin is thin and fragile. Pressure injuries (bedsores) form over bony areas when pressure reduces blood flow.",
        "Prevention includes repositioning at least every 2 hours, keeping skin clean and dry, good nutrition, and using pressure-relieving devices. Aides give baths, back rubs, and nail and hair care, and report redness or skin breaks.",
    ], ["Pressure injuries form over bony areas", "Reposition at least every 2 hours", "Keep skin clean and dry", "Report redness or broken skin"]),
    (15, "Musculoskeletal System: Arthritis, Body Mechanics, and Restorative Care", [
        "The musculoskeletal system supports and moves the body. Common conditions include arthritis (osteoarthritis and rheumatoid arthritis), osteoporosis, fractures, and hip replacements.",
        "Aides use proper body mechanics (wide base, bend at knees, keep back straight) and assist with transfers, ambulation with canes and walkers, and range-of-motion exercises to prevent contractures. Restorative care helps clients regain independence.",
    ], ["Use proper body mechanics", "ROM exercises prevent contractures", "Assist with canes and walkers", "Restorative care builds independence"]),
    (16, "Nervous System", [
        "The nervous system controls body activities. Conditions include stroke (CVA), Parkinson disease, multiple sclerosis, and spinal cord injuries. A stroke may cause one-sided weakness, speech problems (aphasia), and swallowing difficulty.",
        "Aides support clients by placing items on the unaffected side, encouraging self-care, assisting with communication, and preventing falls. Seizures require protecting the client from injury and reporting immediately.",
    ], ["Stroke = CVA; may cause one-sided weakness", "Aphasia = speech difficulty", "Encourage use of the affected side as directed", "Protect the client during a seizure"]),
    (17, "Circulatory System", [
        "The heart pumps blood through arteries, veins, and capillaries. Common conditions include hypertension, coronary artery disease, angina, heart attack, heart failure, and peripheral vascular disease.",
        "Aides monitor vital signs, encourage prescribed diets (low sodium, low fat), help with activity as tolerated, and report chest pain, shortness of breath, or swelling. Anti-embolism stockings may be ordered to improve circulation.",
    ], ["Report chest pain and shortness of breath", "Heart failure causes swelling", "Low-sodium diet for heart conditions", "Anti-embolism stockings improve circulation"]),
    (18, "Respiratory System", [
        "The respiratory system brings in oxygen and removes carbon dioxide. Conditions include COPD (emphysema and chronic bronchitis), asthma, pneumonia, and lung cancer.",
        "Aides help clients breathe easier by positioning them upright, encouraging deep breathing and coughing, and following oxygen safety rules: no smoking or open flames near oxygen. Report breathing difficulty or blue color (cyanosis).",
    ], ["Upright positioning eases breathing", "No smoking or flames near oxygen", "COPD = emphysema + chronic bronchitis", "Report cyanosis"]),
    (19, "Reproductive System", [
        "The reproductive system includes male and female organs. Common conditions include prostate enlargement, breast and prostate cancer, menopause, and sexually transmitted infections.",
        "Aides respect privacy and sexuality, provide perineal care, and report discharge, bleeding, or pain.",
    ], ["Respect privacy and sexuality", "Provide perineal care", "Report discharge or bleeding", "Menopause is a normal change"]),
    (20, "Endocrine System and Diabetes", [
        "Endocrine glands produce hormones. Diabetes mellitus occurs when the body doesn't make or use insulin properly, causing high blood sugar. Type 1 requires insulin; type 2 is linked to obesity and inactivity.",
        "Signs of hypoglycemia (low blood sugar) include shakiness, sweating, and confusion; hyperglycemia causes thirst, frequent urination, and fatigue. Aides follow the diabetic diet, encourage exercise, provide careful foot care, and report symptoms.",
    ], ["Type 1 needs insulin; type 2 linked to lifestyle", "Hypoglycemia: shaky, sweaty, confused", "Hyperglycemia: thirst, urination", "Careful foot care for diabetics"]),
    (21, "Caring for the Client Who Is Terminally Ill", [
        "Terminally ill clients have an illness that is expected to cause death. Hospice care focuses on comfort, dignity, and support for the client and family rather than cure. Clients may move through stages of grief: denial, anger, bargaining, depression, and acceptance.",
        "Aides provide comfort measures (pain relief reporting, mouth care, positioning), emotional support, and respect for advance directives and cultural beliefs. Postmortem care is done with respect.",
    ], ["Hospice = comfort care", "Stages of grief: denial, anger, bargaining, depression, acceptance", "Respect advance directives", "Mouth care and positioning provide comfort"]),
    (22, "Caring for the Client with Alzheimer's Disease", [
        "Alzheimer disease is a progressive dementia that destroys memory, thinking, and the ability to care for oneself. Behaviors may include wandering, agitation, sundowning (increased confusion late in the day), and repeating questions.",
        "Aides use calm, simple communication, keep routines consistent, reduce distractions, ensure safety (locks, removing hazards), and support caregivers who may experience stress.",
    ], ["Progressive memory loss", "Sundowning = late-day confusion", "Keep routines consistent", "Prevent wandering"]),
    (23, "Caring for the Client with Cancer", [
        "Cancer is uncontrolled growth of abnormal cells that can spread (metastasize). Treatments include surgery, chemotherapy, and radiation, which can cause nausea, fatigue, hair loss, and mouth sores.",
        "Aides support nutrition with small, frequent meals, provide skin and mouth care, help manage fatigue, prevent infection, and offer emotional support.",
    ], ["Metastasis = spread of cancer", "Chemo and radiation side effects", "Small, frequent meals", "Prevent infection"]),
    (24, "Maternal Care", [
        "Home health aides may care for new mothers after childbirth (the postpartum period). They observe bleeding (lochia), help with hygiene, encourage rest and good nutrition, and support breastfeeding.",
        "Aides watch for warning signs such as heavy bleeding, fever, or signs of postpartum depression and report them. They also help with household tasks and other children.",
    ], ["Postpartum = after childbirth", "Lochia = postpartum discharge", "Report heavy bleeding or fever", "Watch for postpartum depression"]),
    (25, "Infant Care", [
        "Infant care includes feeding (breast or bottle), burping, diapering, bathing, umbilical cord care, and safe sleep. Infants should sleep on their backs in a crib without loose bedding to reduce the risk of SIDS.",
        "Aides support the infant's head, check bath water temperature, never leave a baby unattended on a surface, and report signs of illness such as fever, poor feeding, or dehydration.",
    ], ["Back to sleep reduces SIDS risk", "Support the infant's head", "Never leave a baby unattended", "Report fever and poor feeding"]),
    (26, "Job-Seeking Skills", [
        "Finding a job involves identifying openings, preparing a résumé, completing applications neatly and honestly, and interviewing well: dressing professionally, arriving on time, and making eye contact.",
        "Keeping a job requires dependability, a positive attitude, continuing education, and good work habits. Aides should give proper notice when leaving.",
    ], ["Prepare a résumé", "Dress professionally for interviews", "Dependability keeps jobs", "Give proper notice when leaving"]),
]

